ScalesStringed={};ScalesStringed.updateDisplay=function(updateType){if(updateType=='chord'){InstrumentOptions.elems.stringFrets.removeClass('in_chord chord_root')}else{InstrumentOptions.elems.stringFrets.removeClass('in_scale scale_root in_chord chord_root')}var f,noteElem,nk,snk,s;for(s=0;s<InstrumentOptions.stringTuningAr.length;s++){snk=InstrumentOptions.stringTuningAr[s];for(f=InstrumentOptions.capoFret;f<=instrumentInfo.num_frets_desktop;f++){nk=(snk+f)%Note.allNoteCount;if(updateType=='chord'){if(Chord.chordNoteKeyAr.indexOf(nk)>=0){noteElem=$('#f_'+f).find('.s_'+s);noteElem.addClass('in_chord');if(nk==Chord.noteKey){noteElem.addClass('chord_root')}}}else{if(Scale.scaleNoteKeyAr.indexOf(nk)>=0){noteElem=$('#f_'+f).find('.s_'+s);noteElem.addClass('in_scale');if(nk==Scale.noteKey){noteElem.addClass('scale_root')}}}}}};